//////////////////////////////////\n// ASYNC FILE READ\n//////////////////////////////////////////////////////////////\n\nlet isAwaitReading = false;\nlet pendingReadPromise = null;\nlet pendingReadResolve = null;\nlet pendingReadReject = null;\n\nconst _stripModelsPrefix = (path) => path.replace(/^\\/?models\\//, '');\n\n// reads are split in chunks of READ_CHUNK at most (postMessage cannot send an ArrayBuffer bigger than 2GB).\n// Each chunk is a new ArrayBuffer, garbage once copied to the heap: small chunks keep that garbage small while loading.\n// llama.cpp uploads the weights to the GPU and to rpc workers in reads of 1MB, one round trip to the main thread each,\n// so sequential reads get a read-ahead that grows (8 times the read, then 4 times more each time) up to READ_CHUNK; other reads (small tensors, the loader jumps between them) get only what they ask for\nconst READ_CHUNK = 32 * 1024 * 1024;\nlet readAhead = null; // { name, offset, bytes }: the rest of the last chunk\nlet seqName = null; // the next sequential read is name at seqNext\nlet seqNext = -1;\nlet seqWindow = 0;\n\n// Files of the OPFS cache are read with a sync access handle, straight into the heap: no Blob, no round trip to the main thread\n// (12-25x faster on Android). It is opened when needed and closed after each wasm call, so the cache can change the file in between\nconst opfsFiles = {}; // name -> { path (in OPFS), size, access, failed }\n\n// returns the number of bytes read, or -1 to read the Blob instead\nconst opfsRead = async (name, offset, req_size, out_ptr) => {\n  const f = opfsFiles[name];\n  if (!f || f.failed) return -1;\n  try {\n    if (!f.access) {\n      let dir = await navigator.storage.getDirectory();\n      for (const d of f.path.slice(0, -1))\n        dir = await dir.getDirectoryHandle(d);\n      const handle = await dir.getFileHandle(f.path[f.path.length - 1]);\n      f.access = await handle.createSyncAccessHandle({ mode: 'read-only' });\n      if (f.access.getSize() !== f.size) {\n        throw new Error('the file in the cache changed');\n      }\n      if (!f.used) {\n        f.used = true;\n        msg({\n          verb: 'console.debug',\n          args: [`Reading ${name} with an OPFS sync access handle`],\n        });\n      }\n    }\n    return f.access.read(getHeapU8().subarray(out_ptr, out_ptr + req_size), {\n      at: offset,\n    });\n  } catch (err) {\n    // for example: another tab has the file open, or the browser does not have sync access handles\n    f.failed = true;\n    msg({\n      verb: 'console.warn',\n      args: [\n        `Cannot read ${name} with an OPFS sync access handle, reading the Blob instead: ${err}`,\n      ],\n    });\n    return -1;\n  }\n};\n\nconst opfsCloseAll = () => {\n  for (const f of Object.values(opfsFiles)) {\n    if (f.access) {\n      try {\n        f.access.close();\n      } catch {}\n      f.access = null;\n    }\n  }\n};\n\n// Called from EM_ASYNC_JS stub in cpp/wllama-patch.cpp (path is already a JS string)\nconst _wllama_js_file_read = async (path, offset, req_size, out_ptr) => {\n  const name = _stripModelsPrefix(path);\n  const n = await opfsRead(name, offset, req_size, out_ptr);\n  if (n >= 0) return n;\n  let total = 0;\n  while (total < req_size) {\n    const pos = offset + total;\n    const left = req_size - total;\n    const ra = readAhead;\n    if (\n      ra &&\n      ra.name === name &&\n      pos >= ra.offset &&\n      pos < ra.offset + ra.bytes.length\n    ) {\n      const start = pos - ra.offset;\n      const n = Math.min(left, ra.bytes.length - start);\n      getHeapU8().set(ra.bytes.subarray(start, start + n), out_ptr + total);\n      total += n;\n      seqName = name;\n      seqNext = pos + n;\n      continue;\n    }\n    const sequential = name === seqName && pos === seqNext;\n    seqWindow = sequential ? Math.max(seqWindow * 4, left * 8) : 0;\n    const size = Math.min(READ_CHUNK, Math.max(left, seqWindow));\n    const bytes = await readFileBytes(name, pos,